"use client";

import { Button } from "../motion/button/base";

import { useEffect, useRef, useState, type CSSProperties } from "react";
import { Check, Loader2, Magnet, Repeat2, X } from "lucide-react";
import { TrimLocaleContext, useTrimLabels, type VideoTrimLocale } from "./labels";
import { useTrimPreview } from "./use-trim-preview";
import { createThumbnailStrip } from "./thumbnail-strip";
import { VideoTrimSelection } from "./video-trim-selection";
import { trimVideo } from "./trim-video";
import type { VideoTrimRange } from "./trim-range";
import "./video-trim.css";

export interface VideoTrimResult {
  range: VideoTrimRange;
  duration: number;
  width: number;
  height: number;
}
export interface VideoTrimProps {
  /** Source URL or object URL. Remote sources must allow CORS. */
  src: string;
  poster?: string;
  /** Receives an MP4 blob; the host owns downloading or uploading it. */
  onExport: (blob: Blob, result: VideoTrimResult) => void | Promise<void>;
  onRangeChange?: (range: VideoTrimRange) => void;
  onError?: (error: Error) => void;
  onClose?: () => void;
  locale?: VideoTrimLocale;
  className?: string;
  style?: CSSProperties;
}

export default function VideoTrim(props: VideoTrimProps) {
  return <TrimLocaleContext.Provider value={props.locale ?? "zh-CN"}>
    <VideoTrimPlayer key={props.src} {...props} />
  </TrimLocaleContext.Provider>;
}

function VideoTrimPlayer(props: VideoTrimProps) {
  const [video, setVideo] = useState<HTMLVideoElement | null>(null);
  const t = useTrimLabels();
  return <section className={`media-rig-trim ${props.className ?? ""}`} style={props.style} aria-label={t("title")}>
    <video ref={setVideo} src={props.src} poster={props.poster} crossOrigin="anonymous" controls playsInline preload="metadata" aria-label={t("title")} />
    {video && <TrimControls {...props} video={video} />}
  </section>;
}

function TrimControls({ src, video, onExport, onRangeChange, onError, onClose }: VideoTrimProps & { video: HTMLVideoElement }) {
  const t = useTrimLabels();
  const [loop, setLoop] = useState(true);
  const [snap, setSnap] = useState(false);
  const trim = useTrimPreview(video, loop);
  const [thumbnails, setThumbnails] = useState<string[]>([]);
  const [thumbnailError, setThumbnailError] = useState(false);
  const [busy, setBusy] = useState(false);
  const [progress, setProgress] = useState<number | null>(null);
  const [failed, setFailed] = useState(false);
  const job = useRef<AbortController | null>(null);
  const callbacks = useRef({ onExport, onRangeChange, onError, onClose });
  useEffect(() => { callbacks.current = { onExport, onRangeChange, onError, onClose }; });
  useEffect(() => {
    const abort = new AbortController();
    void createThumbnailStrip(src, abort.signal).then(images => {
      if (!abort.signal.aborted) setThumbnails(images);
    }).catch(() => { if (!abort.signal.aborted) setThumbnailError(true); });
    return () => { abort.abort(); job.current?.abort(); video.pause(); };
  }, [src, video]);
  useEffect(() => {
    if (trim.duration > 0) callbacks.current.onRangeChange?.([...trim.range]);
  }, [trim.duration, trim.range]);
  useEffect(() => {
    if (trim.error) callbacks.current.onError?.(new Error("Could not load or play video"));
  }, [trim.error]);
  useEffect(() => {
    if (!onClose) return;
    const escape = (event: KeyboardEvent) => {
      if (event.key === "Escape") { job.current?.abort(); callbacks.current.onClose?.(); }
    };
    // Scoped to this component so multiple embedded editors do not close together.
    const root = video.parentElement;
    root?.addEventListener("keydown", escape);
    return () => root?.removeEventListener("keydown", escape);
  }, [onClose, video]);
  const cancel = () => {
    job.current?.abort();
    job.current = null;
    setBusy(false);
    setProgress(null);
  };
  const generate = async () => {
    if (job.current || trim.error || trim.duration <= 0) return;
    const controller = new AbortController();
    job.current = controller;
    const range: VideoTrimRange = [...trim.range];
    setBusy(true); setFailed(false); setProgress(null); video.pause();
    try {
      const blob = await trimVideo({ src, range, signal: controller.signal, onProgress: value => {
        if (!controller.signal.aborted) setProgress(value);
      } });
      controller.signal.throwIfAborted();
      await callbacks.current.onExport(blob, { range, duration: range[1] - range[0], width: Math.ceil(video.videoWidth / 2) * 2, height: Math.ceil(video.videoHeight / 2) * 2 });
    } catch (cause) {
      if (!controller.signal.aborted) {
        setFailed(true);
        callbacks.current.onError?.(cause instanceof Error ? cause : new Error(String(cause)));
      }
    } finally {
      if (job.current === controller) { job.current = null; if (!controller.signal.aborted) setBusy(false); }
    }
  };
  const ready = trim.duration > 0 && !trim.error;
  const label = busy ? progress === null ? t("preparing") : t("generating", { percent: progress }) : t("generate");
  return <div className="media-rig-trim__panel">
    <div className="media-rig-trim__toolbar">
      {onClose && <Button variant="ghost" size="icon" type="button" className="media-rig-trim__icon" aria-label={t("cancel")} title={t("cancel")} onClick={() => { cancel(); onClose(); }}><X size={17} /></Button>}
      <div className="media-rig-trim__timeline-wrap">
        <div className="media-rig-trim__timeline">
          <div className="media-rig-trim__thumbnails" aria-hidden="true">
            {thumbnails.map((url, index) => <img key={index} src={url} alt="" draggable={false} />)}
            {ready && <>
              <div className="media-rig-trim__shade" style={{ left: 0, width: `${trim.range[0] / trim.duration * 100}%` }} />
              <div className="media-rig-trim__shade" style={{ right: 0, width: `${(1 - trim.range[1] / trim.duration) * 100}%` }} />
            </>}
          </div>
          {ready && <VideoTrimSelection range={trim.range} duration={trim.duration} snap={snap} disabled={busy} onChange={trim.changeRange} onDragStart={trim.beginDrag} onDragEnd={trim.endDrag} />}
          {!ready && !trim.error && <span role="status" className="media-rig-trim__loading">{t("loading")}</span>}
        </div>
        {ready && <div className="media-rig-trim__times"><span>{trim.range[0].toFixed(2)} s</span><span>{trim.range[1].toFixed(2)} s</span></div>}
      </div>
      <div className="media-rig-trim__actions">
        <Button variant="ghost" size="icon" type="button" className="media-rig-trim__icon" aria-label={t(snap ? "disableSnap" : "enableSnap")} title={t(snap ? "disableSnap" : "enableSnap")} aria-pressed={snap} disabled={busy} onClick={() => setSnap(!snap)}><Magnet size={17} /></Button>
        <Button variant="ghost" size="icon" type="button" className="media-rig-trim__icon" aria-label={t(loop ? "disableLoop" : "enableLoop")} title={t(loop ? "disableLoop" : "enableLoop")} aria-pressed={loop} disabled={busy} onClick={() => setLoop(!loop)}><Repeat2 size={18} /></Button>
        <Button variant="ghost" size="icon" type="button" className="media-rig-trim__icon media-rig-trim__confirm" aria-label={label} title={label} aria-busy={busy} disabled={!ready || busy} onClick={() => void generate()}>{busy ? <Loader2 size={18} className="media-rig-trim__spinner" /> : <Check size={18} />}</Button>
        {busy && <Button variant="ghost" size="icon" type="button" className="media-rig-trim__icon" aria-label={t("cancelExport")} title={t("cancelExport")} onClick={cancel}><X size={17} /></Button>}
      </div>
    </div>
    {busy && <p role="status">{label}</p>}
    {failed && <p role="alert">{t("error")}</p>}
    {trim.error && <p role="alert">{t("mediaError")}</p>}
    {thumbnailError && <p role="status">{t("thumbnailError")}</p>}
  </div>;
}

"use client";

export { default as VideoTrim } from "./VideoTrim";
export type { VideoTrimProps, VideoTrimResult } from "./VideoTrim";
export type { VideoTrimRange } from "./trim-range";
export type { VideoTrimLocale } from "./labels";
export { trimVideo } from "./trim-video";

import { createContext, useContext } from "react";

const zh = {
  title: "片段截取", cancel: "取消截取", start: "截取起点", end: "截取终点", move: "移动选区", seconds: "{seconds} 秒",
  enableSnap: "开启整数秒吸附", disableSnap: "关闭整数秒吸附", enableLoop: "开启选区循环播放", disableLoop: "关闭选区循环播放",
  generate: "生成片段", loading: "正在读取视频…", preparing: "正在加载截取引擎…", generating: "正在截取… {percent}%",
  error: "截取失败，请检查视频是否可访问后重试，或尝试更小的视频。", mediaError: "无法读取或播放视频，请更换视频后重试。",
  thumbnailError: "缩略图暂不可用，仍可调整选区并预览。", cancelExport: "取消生成",
};
const en: typeof zh = {
  title: "Video trim", cancel: "Close trim", start: "Trim start", end: "Trim end", move: "Move selection", seconds: "{seconds} s",
  enableSnap: "Enable whole-second snapping", disableSnap: "Disable whole-second snapping", enableLoop: "Enable selection loop", disableLoop: "Disable selection loop",
  generate: "Generate clip", loading: "Loading video…", preparing: "Loading video engine…", generating: "Trimming… {percent}%",
  error: "Could not export. Check the video URL or try a smaller video.", mediaError: "Could not load or play this video. Try another video.",
  thumbnailError: "Thumbnails unavailable. You can still adjust and preview the selection.", cancelExport: "Cancel export",
};
export type VideoTrimLocale = "zh-CN" | "en-US";
export const TrimLocaleContext = createContext<VideoTrimLocale>("zh-CN");
export function useTrimLabels() {
  const dictionary = useContext(TrimLocaleContext) === "en-US" ? en : zh;
  return (key: string, values: Record<string, string | number> = {}) => {
    const label = dictionary[key.replace("videoTrim.", "") as keyof typeof zh] ?? key;
    return label.replace(/\{(\w+)\}/g, (_, name: string) => String(values[name] ?? ""));
  };
}

function waitForMedia(
  video: HTMLVideoElement,
  event: string,
  signal: AbortSignal,
  action: () => void,
) {
  return new Promise<void>((resolve, reject) => {
    const cleanup = () => {
      clearTimeout(timer);
      video.removeEventListener(event, done);
      video.removeEventListener("error", fail);
      signal.removeEventListener("abort", fail);
    };
    const done = () => {
      cleanup();
      resolve();
    };
    const fail = () => {
      cleanup();
      reject(new Error("Video frame unavailable"));
    };
    const timer = setTimeout(fail, 15_000);
    video.addEventListener(event, done, { once: true });
    video.addEventListener("error", fail, { once: true });
    signal.addEventListener("abort", fail, { once: true });
    if (signal.aborted) {
      fail();
      return;
    }
    try {
      action();
    } catch {
      fail();
    }
  });
}

export async function createThumbnailStrip(
  src: string,
  signal: AbortSignal,
): Promise<string[]> {
  const video = document.createElement("video");
  video.crossOrigin = "anonymous";
  video.muted = true;
  video.preload = "auto";
  const urls: string[] = [];
  try {
    await waitForMedia(video, "loadeddata", signal, () => {
      video.src = src;
      video.load();
    });
    if (!Number.isFinite(video.duration) || video.duration <= 0)
      throw new Error("Invalid duration");
    const canvas = document.createElement("canvas");
    canvas.width = 144;
    canvas.height = Math.max(
      1,
      Math.round((144 * video.videoHeight) / video.videoWidth),
    );
    const context = canvas.getContext("2d");
    if (!context) throw new Error("Canvas unavailable");
    for (let i = 0; i < 12; i++) {
      signal.throwIfAborted();
      const time = (video.duration * (i + 0.5)) / 12;
      await waitForMedia(video, "seeked", signal, () => {
        video.currentTime = time;
      });
      context.drawImage(video, 0, 0, canvas.width, canvas.height);
      urls.push(canvas.toDataURL("image/jpeg", 0.65));
    }
    return urls;
  } finally {
    video.pause();
    video.removeAttribute("src");
    video.load();
  }
}

export type VideoTrimRange = [number, number];
export type VideoTrimHandle = "start" | "end" | "move";

export function adjustVideoTrimRange(
  range: VideoTrimRange,
  handle: VideoTrimHandle,
  delta: number,
  duration: number,
  snap: boolean,
): VideoTrimRange {
  const minimum = Math.min(0.1, duration);
  const clamp = (value: number, min: number, max: number) =>
    Math.max(min, Math.min(max, value));
  const target = (value: number) => (snap ? Math.round(value) : value);
  if (handle === "start")
    return [clamp(target(range[0] + delta), 0, range[1] - minimum), range[1]];
  if (handle === "end")
    return [
      range[0],
      clamp(target(range[1] + delta), range[0] + minimum, duration),
    ];
  const length = range[1] - range[0];
  const start = clamp(target(range[0] + delta), 0, duration - length);
  return [start, start + length];
}

import type { VideoTrimRange } from "./trim-range";

import { withVideoEngine } from "./video-engine";

export async function trimVideo({
  src,
  range,
  signal,
  onProgress,
}: {
  src: string;
  range: VideoTrimRange;
  signal: AbortSignal;
  onProgress: (percent: number | null) => void;
}): Promise<Blob> {
  const [start, end] = range;
  if (
    !Number.isFinite(start) ||
    !Number.isFinite(end) ||
    start < 0 ||
    end <= start
  )
    throw new Error("Invalid video trim range");
  onProgress(null);
  return withVideoEngine(src, signal, async (ffmpeg, engineSignal) => {
    onProgress(0);
    ffmpeg.on("progress", ({ time }) => {
      if (!engineSignal.aborted)
        onProgress(
          Math.max(
            0,
            Math.min(99, Math.floor((time / 1_000_000 / (end - start)) * 100)),
          ),
        );
    });
    const exitCode = await ffmpeg.exec(
      [
        "-ss",
        start.toFixed(6),
        "-i",
        "input",
        "-t",
        (end - start).toFixed(6),
        "-map",
        "0:v:0",
        "-map",
        "0:a:0?",
        "-vf",
        "pad=ceil(iw/2)*2:ceil(ih/2)*2",
        "-c:v",
        "libx264",
        "-preset",
        "ultrafast",
        "-crf",
        "18",
        "-pix_fmt",
        "yuv420p",
        "-c:a",
        "aac",
        "-b:a",
        "192k",
        "-movflags",
        "+faststart",
        "output.mp4",
      ],
      900_000,
      { signal: engineSignal },
    );
    if (exitCode !== 0) throw new Error("Video encoding failed");
    const data = await ffmpeg.readFile("output.mp4", "binary", {
      signal: engineSignal,
    });
    engineSignal.throwIfAborted();
    if (typeof data === "string" || data.byteLength === 0)
      throw new Error("Empty video output");
    onProgress(100);
    return new Blob([new Uint8Array(data)], { type: "video/mp4" });
  });
}

import { useCallback, useEffect, useRef, useState } from "react";
import type { VideoTrimRange } from "./trim-range";

export function useTrimPreview(video: HTMLVideoElement, loop: boolean) {
  const [duration, setDuration] = useState(0);
  const [range, setRange] = useState<VideoTrimRange>([0, 0]);
  const [error, setError] = useState(false);
  const rangeRef = useRef(range);
  const loopRef = useRef(loop);
  const dragging = useRef(false);
  const resume = useRef(false);

  useEffect(() => {
    loopRef.current = loop;
  }, [loop]);

  useEffect(() => {
    const previousTime = video.currentTime;
    video.pause();
    const metadata = () => {
      const length = Number.isFinite(video.duration) ? video.duration : 0;
      setDuration(length);
      const next: VideoTrimRange = [0, Math.min(5, length)];
      rangeRef.current = next;
      setRange(next);
      setError(length <= 0);
    };
    if (video.readyState >= 1) metadata();
    video.addEventListener("loadedmetadata", metadata);
    const failed = () => setError(true);
    video.addEventListener("error", failed);
    let frame = 0;
    const sync = () => {
      const [start, end] = rangeRef.current;
      if (
        loopRef.current &&
        !dragging.current &&
        end > start &&
        !video.seeking
      ) {
        if ((!video.paused || video.ended) && video.currentTime >= end) {
          video.currentTime = start;
          if (video.paused) void video.play().catch(failed);
        } else if (!video.paused && video.currentTime < start) {
          video.currentTime = start;
        }
      }
    };
    const tick = () => {
      sync();
      frame = requestAnimationFrame(tick);
    };
    const onPlay = () => {
      const [start, end] = rangeRef.current;
      if (
        loopRef.current &&
        (video.currentTime < start || video.currentTime >= end)
      )
        video.currentTime = start;
      sync();
    };
    video.addEventListener("play", onPlay);
    video.addEventListener("timeupdate", sync);
    video.addEventListener("ended", sync);
    frame = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(frame);
      video.removeEventListener("loadedmetadata", metadata);
      video.removeEventListener("error", failed);
      video.removeEventListener("play", onPlay);
      video.removeEventListener("timeupdate", sync);
      video.removeEventListener("ended", sync);
      if (loopRef.current) {
        video.pause();
        if (video.readyState >= 1) video.currentTime = previousTime;
      }
    };
  }, [video]);

  const changeRange = useCallback(
    (next: VideoTrimRange, previewEnd = false) => {
      rangeRef.current = next;
      setRange(next);
      video.currentTime = previewEnd
        ? Math.max(next[0], next[1] - 0.001)
        : next[0];
    },
    [video],
  );
  const beginDrag = () => {
    dragging.current = true;
    resume.current = !video.paused;
    video.pause();
  };
  const endDrag = () => {
    if (!dragging.current) return;
    dragging.current = false;
    video.currentTime = rangeRef.current[0];
    if (resume.current) void video.play().catch(() => setError(true));
  };
  return {
    duration,
    range,
    changeRange,
    beginDrag,
    endDrag,
    error,
  };
}

import type { FFmpeg } from "@ffmpeg/ffmpeg";

// One isolated worker per operation; shared setup for trim and separation.
const CORE_BASE_URL =
  "https://cdn.jsdelivr.net/npm/@ffmpeg/core@0.12.10/dist/esm";

export async function withVideoEngine<T>(
  src: string,
  signal: AbortSignal,
  run: (ffmpeg: FFmpeg, signal: AbortSignal) => Promise<T>,
): Promise<T> {
  signal.throwIfAborted();
  const [{ FFmpeg }, { fetchFile }] = await Promise.all([
    import("@ffmpeg/ffmpeg"),
    import("@ffmpeg/util"),
  ]);
  signal.throwIfAborted();
  const ffmpeg = new FFmpeg();
  const controller = new AbortController();
  const abort = () => {
    controller.abort();
    ffmpeg.terminate();
  };
  signal.addEventListener("abort", abort, { once: true });
  const loadingTimeout = setTimeout(abort, 120_000);
  const urls: string[] = [];
  const loadBlob = async (url: string) => {
    const response = await fetch(url, { signal: controller.signal });
    if (!response.ok)
      throw new Error(`Video source fetch failed: ${response.status}`);
    const blob = await response.blob();
    controller.signal.throwIfAborted();
    return blob;
  };
  const coreAsset = async (name: string, type: string, base = CORE_BASE_URL) => {
    const blob = await loadBlob(`${base}/${name}`);
    controller.signal.throwIfAborted();
    const url = URL.createObjectURL(new Blob([blob], { type }));
    urls.push(url);
    return url;
  };
  try {
    const [coreURL, wasmURL] = await Promise.all([
      coreAsset("ffmpeg-core.js", "text/javascript"),
      coreAsset("ffmpeg-core.wasm", "application/wasm"),
    ]);
    try {
      await ffmpeg.load({ coreURL, wasmURL }, { signal: controller.signal });
    } catch {
      controller.signal.throwIfAborted();
      // Webpack emits a classic worker and rewrites the upstream dynamic import.
      // Retry with the classic core; Vite/module workers use the ESM core above.
      const classicURL = await coreAsset("ffmpeg-core.js", "text/javascript", CORE_BASE_URL.replace("/esm", "/umd"));
      await ffmpeg.load({ coreURL: classicURL, wasmURL }, { signal: controller.signal });
    }
    const source = await loadBlob(src);
    await ffmpeg.writeFile("input", await fetchFile(source), {
      signal: controller.signal,
    });
    clearTimeout(loadingTimeout);
    return await run(ffmpeg, controller.signal);
  } finally {
    clearTimeout(loadingTimeout);
    controller.abort();
    signal.removeEventListener("abort", abort);
    ffmpeg.terminate();
    urls.forEach((url) => URL.revokeObjectURL(url));
  }
}

import { useRef, type PointerEvent, type KeyboardEvent } from "react";
import { useTrimLabels } from "./labels";
import {
  adjustVideoTrimRange,
  type VideoTrimHandle,
  type VideoTrimRange,
} from "./trim-range";

export function VideoTrimSelection({
  range,
  duration,
  snap,
  disabled,
  onChange,
  onDragStart,
  onDragEnd,
}: {
  range: VideoTrimRange;
  duration: number;
  snap: boolean;
  disabled: boolean;
  onChange: (range: VideoTrimRange, previewEnd?: boolean) => void;
  onDragStart: () => void;
  onDragEnd: () => void;
}) {
  const t = useTrimLabels();
  const track = useRef<HTMLDivElement>(null);
  const drag = useRef<{
    id: number;
    x: number;
    width: number;
    range: VideoTrimRange;
    handle: VideoTrimHandle;
  } | null>(null);
  const start = (
    event: PointerEvent<HTMLButtonElement>,
    handle: VideoTrimHandle,
  ) => {
    event.preventDefault();
    event.stopPropagation();
    const width = track.current?.getBoundingClientRect().width ?? 0;
    if (disabled || !width || event.button !== 0) return;
    drag.current = {
      id: event.pointerId,
      x: event.clientX,
      width,
      range: [...range],
      handle,
    };
    event.currentTarget.setPointerCapture(event.pointerId);
    onDragStart();
  };
  const move = (event: PointerEvent<HTMLButtonElement>) => {
    const current = drag.current;
    if (!current || current.id !== event.pointerId || disabled) return;
    onChange(
      adjustVideoTrimRange(
        current.range,
        current.handle,
        ((event.clientX - current.x) / current.width) * duration,
        duration,
        snap,
      ),
      current.handle === "end",
    );
  };
  const finish = () => {
    if (!drag.current) return;
    drag.current = null;
    onDragEnd();
  };
  const end = (event: PointerEvent<HTMLButtonElement>) => {
    finish();
    if (event.currentTarget.hasPointerCapture(event.pointerId))
      event.currentTarget.releasePointerCapture(event.pointerId);
  };
  const key = (
    event: KeyboardEvent<HTMLButtonElement>,
    handle: VideoTrimHandle,
  ) => {
    if (disabled) return;
    const step = snap ? 1 : 0.01;
    let delta: number;
    if (event.key === "ArrowLeft") delta = -(event.shiftKey ? 1 : step);
    else if (event.key === "ArrowRight") delta = event.shiftKey ? 1 : step;
    else if (event.key === "Home") delta = -duration;
    else if (event.key === "End") delta = duration;
    else return;
    event.preventDefault();
    event.stopPropagation();
    onChange(
      adjustVideoTrimRange(range, handle, delta, duration, snap),
      handle === "end",
    );
  };
  return (
    <div ref={track} className="media-rig-trim__selection-track">
      <div
        className="media-rig-trim__selection"
        style={{
          left: `${(range[0] / duration) * 100}%`,
          width: `${((range[1] - range[0]) / duration) * 100}%`,
        }}
      >
        {/* One continuous border joins the rails and handles without overlapping fills. */}
        <div
          aria-hidden="true"
          className="media-rig-trim__selection-border"
        />
        <button type="button"
          disabled={disabled}
          aria-label={t("videoTrim.move")}
          className="media-rig-trim__move"
          onPointerDown={(event) => start(event, "move")}
          onPointerMove={move}
          onPointerUp={end}
          onPointerCancel={end}
          onLostPointerCapture={finish}
          onKeyDown={(event) => key(event, "move")}
        >
          <span className="media-rig-trim__length">
            {t("videoTrim.seconds", {
              seconds: (range[1] - range[0]).toFixed(2),
            })}
          </span>
        </button>
        {(["start", "end"] as const).map((handle) => (
          <button type="button"
            key={handle}
            role="slider"
            aria-label={t(`videoTrim.${handle}`)}
            aria-valuemin={
              handle === "start" ? 0 : range[0] + Math.min(0.1, duration)
            }
            aria-valuemax={
              handle === "start" ? range[1] - Math.min(0.1, duration) : duration
            }
            aria-valuenow={handle === "start" ? range[0] : range[1]}
            disabled={disabled}
            className="media-rig-trim__handle"
            style={handle === "start" ? { left: -12 } : { right: -12 }}
            onPointerDown={(event) => start(event, handle)}
            onPointerMove={move}
            onPointerUp={end}
            onPointerCancel={end}
            onLostPointerCapture={finish}
            onKeyDown={(event) => key(event, handle)}
          >
            <span
              aria-hidden="true"
              className="media-rig-trim__grip"
            >
              <span className="media-rig-trim__grip-line" />
            </span>
          </button>
        ))}
      </div>
    </div>
  );
}

